public static void check(Solution solution) {
    assert Arrays.equals(solution.longestWord(new int[]{"a","ab","abc","abcd","abcde","abcdef","abcdefg","abcdefgh"}), abcdefgh);
    assert Arrays.equals(solution.longestWord(new int[]{"a","b","c"}), a);
    assert Arrays.equals(solution.longestWord(new int[]{"w","wo","wor","worl","world"}), world);
    assert Arrays.equals(solution.longestWord(new int[]{"zebra","zeb","zebu","zebrae","zebraes","zebraest"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"car","cars","carp","card","care","career","caree","careerl","careerle","careerled"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"a","banana","app","appl","ap","apply","apple"}), apple);
    assert Arrays.equals(solution.longestWord(new int[]{"hello","hell","he","h","hero","her","here","heroic"}), here);
    assert Arrays.equals(solution.longestWord(new int[]{"ab","abc","bc","abcd"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"layer","layers","layered","layering","layerss"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"abcd","abc","ab","a"}), abcd);
    assert Arrays.equals(solution.longestWord(new int[]{"cat","banana","dog","do","doge"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"apple","ape","app","appl","ap","application"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"yo","yolo","yell","yes","yellow","ye","yellower"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"sgz","sgzn","sgznwv","i","ksiaz","ksiazx","ksiazxp","iwc","iwcx","iwcxz","iwcxzo"}), i);
    assert Arrays.equals(solution.longestWord(new int[]{"apple","app","ap","appl","apply"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"ab","abc","bcd","abcd","abcde"}), null);
    assert Arrays.equals(solution.longestWord(new int[]{"yo","yoyomo","yoymomo","yoyomomo"}), null);
